/**
 * Return one page of the Bots that need the person, have something unread for them, or that they paused: per Bot, its questions, approvals, stalled handoffs, check-in items and tasks waiting on them. Each page also carries the person's newest ping, so a client notifies once per ping however many items it carried. Ordered by the Bot's name, then its id. It is the person's own: nobody else, an administrator included, may read it. A missing cursor starts at the first page and nextCursor null ends the list.
 * @summary List what each Bot has waiting on a person
 */

export const listBotAttentionPathPersonIdMax = 200;

export const listBotAttentionPathPersonIdRegExp = new RegExp("\\S");

export const ListBotAttentionParams = zod.object({
  organizationId: zod
    .string()
    .min(1)
    .describe(
      "The organization, by its id or its slug. One the caller is not a member of answers as one that does not exist, `default` included.",
    ),
  personId: zod
    .string()
    .min(1)
    .max(listBotAttentionPathPersonIdMax)
    .regex(listBotAttentionPathPersonIdRegExp)
    .describe(
      "The person: me for the caller, or a person's id. A person's own things (their instructions, preferences, API keys, sessions and linked accounts) answer only the person themselves, by either.",
    ),
});

export const listBotAttentionQueryLimitDefault = 50;
export const listBotAttentionQueryLimitMax = 100;

export const listBotAttentionQueryCursorMax = 4096;

export const listBotAttentionQueryCursorRegExp = new RegExp("^[A-Za-z0-9_-]+$");

export const ListBotAttentionQueryParams = zod.object({
  limit: zod
    .int()
    .min(1)
    .max(listBotAttentionQueryLimitMax)
    .default(listBotAttentionQueryLimitDefault)
    .describe("Most items in one page."),
  cursor: zod
    .string()
    .min(1)
    .max(listBotAttentionQueryCursorMax)
    .regex(listBotAttentionQueryCursorRegExp)
    .optional()
    .describe(
      "Opaque continuation from the previous page's nextCursor, bound to the organization and the filters that made it. The server only ever issues cursors written in URL-safe base64 (letters, digits, - and _, no padding) and refuses anything else, so the pattern says so. A cursor that fits the pattern can still be refused: one this list never gave out, or one made for another organization or other filters.",
    ),
});

